/** ico(name, size, cls) của bản cũ. */
export function Ico({ n, sz = 16, cls = "", ...rest }: { n: string; sz?: number; cls?: string } & Omit<SVGProps<SVGSVGElement>, "className">) {
  return <svg className={"i " + cls} width={sz} height={sz} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={sz <= 14 ? 2 : 1.75} strokeLinecap="round" strokeLinejoin="round" dangerouslySetInnerHTML={{ __html: IC[n] || IC.user }} {...rest} />;
}
/** chuỗi SVG (cho chỗ còn dựng HTML bằng chuỗi: tooltip, canvas sơ đồ…). */
export const icoHtml = (n: string, sz = 16, cls = "") => `<svg class="i ${cls}" width="${sz}" height="${sz}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="${sz <= 14 ? 2 : 1.75}" stroke-linecap="round" stroke-linejoin="round">${IC[n] || IC.user}</svg>`;
